mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY OBJ.REG_DTTM DESC) AS LINE_NO , OBJ.MRK_OBJCT_APLY_ID , DEPT.DEPTNM , SBJ.SBJCT_ID , SBJ.SBJCTNM , SBJ.DVCLAS_NO , USR.USER_RPRS_ID , USR.STDNT_NO , USR.USERNM , OBJ.OBJCT_APLY_STSCD , CD.CDNM , OBJ.CHG_DTTM , COUNT(*) OVER() AS TOTAL_CNT FROM TB_LMS_MRK_OBJCT_APLY OBJ JOIN TB_LMS_SBJCT SBJ ON OBJ.SBJCT_ID = SBJ.SBJCT_ID JOIN TB_LMS_DEPT DEPT ON SBJ.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_USER USR ON OBJ.USER_ID = USR.USER_ID JOIN TB_LMS_ATNDLC STD ON SBJ.SBJCT_ID = STD.SBJCT_ID AND USR.USER_ID = STD.USER_ID JOIN TB_LMS_CMMN_CD CD ON CD.UP_CD = 'OBJCT_APLY_STSCD' AND OBJ.OBJCT_APLY_STSCD = CD.CD WHERE 1=1
AND OBJ.SBJCT_ID = #{sbjctId}
AND OBJ.USER_ID = #{userId}

mapper.select:
/* SQL ID : markObjectionApplyDAO.stdMrkObjctAplyList 설 명 : [학습자] 성적 이의 신청 목록 조회 */ SELECT OBJ.MRK_OBJCT_APLY_ID , DEPT.DEPTNM , SBJ.SBJCT_ID , SBJ.SBJCTNM , SBJ.DVCLAS_NO , USR.USER_RPRS_ID , USR.STDNT_NO , USR.USERNM , OBJ.OBJCT_APLY_STSCD , CD.CDNM , OBJ.CHG_DTTM FROM TB_LMS_MRK_OBJCT_APLY OBJ JOIN TB_LMS_SBJCT SBJ ON OBJ.SBJCT_ID = SBJ.SBJCT_ID JOIN TB_LMS_DEPT DEPT ON SBJ.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_USER USR ON OBJ.USER_ID = USR.USER_ID JOIN TB_LMS_ATNDLC STD ON SBJ.SBJCT_ID = STD.SBJCT_ID AND USR.USER_ID = STD.USER_ID JOIN TB_LMS_CMMN_CD CD ON CD.UP_CD = 'OBJCT_APLY_STSCD' AND OBJ.OBJCT_APLY_STSCD = CD.CD WHERE 1=1
AND OBJ.SBJCT_ID = #{sbjctId}
AND OBJ.USER_ID = #{userId}
ORDER BY OBJ.REG_DTTM

SELECT count(1)
FROM TB_LMS_MRK_OBJCT_APLY OBJ
WHERE 1=1

    AND OBJ.SBJCT_ID = #{sbjctId}


    AND OBJ.USER_ID = #{userId}

mapper.insert:
/*
    SQL ID : markObjectionApplyDAO.stdMrkObjctAplyRegist
    설  명 : [학습자] 성적 이의 신청 등록
*/
INSERT INTO TB_LMS_MRK_OBJCT_APLY (
      MRK_OBJCT_APLY_ID
    , USER_ID
    , SBJCT_ID
    , OBJCT_APLY_CTS
    , OBJCT_APLY_STSCD
    , RGTR_ID
    , REG_DTTM
    , OBJCT_APLY_DTTM
) VALUES (
      #{mrkObjctAplyId}
    , #{userId}
    , #{sbjctId}
    , #{objctAplyCts}
    , 'APLY'
    , #{userId}
    , FN_DTTM()
    , FN_DTTM()
)

mapper.update:
/*
    SQL ID : markObjectionApplyDAO.stdMrkObjctAplyModify
    설  명 : [학습자] 성적 이의 신청 수정
*/
UPDATE TB_LMS_MRK_OBJCT_APLY
SET OBJCT_APLY_CTS = #{objctAplyCts}
WHERE MRK_OBJCT_APLY_ID = #{mrkObjctAplyId}

mapper.delete:
/*
    SQL ID : markObjectionApplyDAO.stdMrkObjctAplyDelete
    설  명 : [학습자] 성적 이의 신청 삭제
*/
DELETE FROM TB_LMS_MRK_OBJCT_APLY
WHERE MRK_OBJCT_APLY_ID = #{mrkObjctAplyId}
